const requested_scopes=rawScopes.filter(s=>typeof s==='string'&&validScopes.includes(s));
if(!rawScopes.length||new Set(requested_scopes).size!==rawScopes.length)missing.push('explicit_valid_requested_scopes');
const kind=typeof art.kind==='string'?art.kind.toUpperCase():'UNKNOWN';
const allowable={TEXT:['TEXT'],IMAGE:['TEXT','IMAGE'],VIDEO:['TEXT','IMAGE','VIDEO','AUDIO'],AUDIO:['TEXT','AUDIO']};
if(!allowable[kind])missing.push('valid_artifact_kind');else if(requested_scopes.some(s=>!allowable[kind].includes(s)))missing.push('scope_incompatible_with_artifact_kind');
const bar=p.bar&&typeof p.bar==='object'?p.bar:{};
const mediaReview=requested_scopes.some(s=>s!=='TEXT');
if(mediaReview&&(p.bar_approved!==true||!Array.isArray(bar.mechanics)||bar.mechanics.length<5||bar.mechanics.length>7))missing.push('approved_bar_5_to_7_mechanics');
if(mediaReview&&(typeof p.benchmark_ref!=='string'||!p.benchmark_ref.trim()))missing.push('accessible_benchmark');
const canon=p.canon&&typeof p.canon==='object'?p.canon:{};
const pack={task_id:p.task_id??null,project_id:p.project_id??null,artifact_id:p.artifact_id??null,artifact_revision:p.artifact_revision??null,
review_round:Number.isInteger(p.review_round)&&p.review_round>0?p.review_round:1,artifact_scope:kind,requested_scopes,
requirements,canon:{revision:canon.revision??null,rules:Array.isArray(canon.rules)?canon.rules:[]},
bar:{revision:bar.revision??null,mechanics:Array.isArray(bar.mechanics)?bar.mechanics:[]},
benchmark_ref:p.benchmark_ref??null,artifact:{kind:art.kind??'unknown',render_refs:Array.isArray(art.render_refs)?art.render_refs:[],text_ref:art.text_ref??null},
missing,safe_mode:'DRAFT_NO_LLM_NO_COST',trusted_backend_evidence_available:false,untrusted_approval_ignored:true};
