const a=$input.all().map(x=>x.json);const roles=['REVIEW-REQ','REVIEW-SYSTEM','REVIEW-CRAFT'];
const counts={};for(const x of a)counts[x.role]=(counts[x.role]??0)+1;
const missingRoles=roles.filter(role=>counts[role]!==1);
const same=a.length===3&&a.every(x=>x.task_id===a[0].task_id&&x.project_id===a[0].project_id&&x.artifact_id===a[0].artifact_id&&x.artifact_revision===a[0].artifact_revision&&x.review_round===a[0].review_round&&JSON.stringify(x.requested_scopes)===JSON.stringify(a[0].requested_scopes));
const requested=a[0]?.requested_scopes??[];const scopes=['TEXT','IMAGE','VIDEO','AUDIO'];
const validScopeList=Array.isArray(requested)&&requested.length>0&&new Set(requested).size===requested.length&&requested.every(s=>scopes.includes(s));
const validRoles=a.length===3&&!missingRoles.length&&same&&validScopeList;
const allowedEvidence={TEXT:['text_quote','transcript_quote'],IMAGE:['image_observation'],VIDEO:['video_frame','video_segment'],AUDIO:['audio_observation']};
function verifiedPass(x){if(x.verdict!=='PASS'||x.evidence_verified_by_backend!==true)return false;if(!Array.isArray(x.checked_scopes)||!Array.isArray(x.evidence)||!x.evidence.length)return false;
return requested.every(s=>x.checked_scopes.includes(s)&&x.scope_results?.[s]==='PASS'&&x.evidence.some(e=>e&&allowedEvidence[s].includes(e.evidence_type)&&((typeof e.source_asset_id==='string'&&e.source_asset_id)||(typeof e.source_text_revision==='string'&&e.source_text_revision))));}
const verdicts=a.map(x=>({role:x.role,model:x.model,verdict:x.verdict,artifact_scope:x.artifact_scope,requested_scopes:x.requested_scopes,checked_scopes:x.checked_scopes??[],scope_results:x.scope_results??{},ready_for_future_review:x.ready_for_future_review,missing_inputs:x.missing_inputs,evidence:x.evidence,biggest_gap:x.biggest_gap}));
const invalidVerdict=a.some(x=>!['PASS','FAIL','BLOCKED'].includes(x.verdict));
const fail=a.some(x=>x.verdict==='FAIL'&&x.evidence_verified_by_backend===true&&Array.isArray(x.evidence)&&x.evidence.length>0);
const blocked=a.some(x=>x.verdict==='BLOCKED');
const passed=validRoles&&!invalidVerdict&&a.every(verifiedPass);
const status=!validRoles||invalidVerdict?'BLOCKED_INVALID_REVIEW_SET':fail?'CHANGES_REQUESTED':blocked?'BLOCKED_AWAITING_INTEGRATION':passed?'AWAITING_OWNER_APPROVAL':'BLOCKED_UNVERIFIED_EVIDENCE';
return[{json:{task_id:a[0]?.task_id??null,project_id:a[0]?.project_id??null,artifact_id:a[0]?.artifact_id??null,artifact_revision:a[0]?.artifact_revision??null,review_round:a[0]?.review_round??1,artifact_scope:a[0]?.artifact_scope??null,requested_scopes:requested,status,all_passed:passed,owner_approval_required:true,paid_calls_executed:false,quality_claim:false,reviewer_count:a.length,missing_or_duplicate_roles:missingRoles,verdicts,next_action:status==='CHANGES_REQUESTED'?'return_evidenced_gap_to_original_builder':status==='AWAITING_OWNER_APPROVAL'?'wait_for_owner_approval':'do_not_dispatch_paid_models; connect trusted backend, evidence scope validator and media inspector'}}];
